package com.hbm.client.generator.stirling;
import com.hbm.hazard.HbmHazards;import com.hbm.machine.generator.stirling.*;import java.util.*;import me.shedaniel.math.*;import me.shedaniel.rei.api.client.gui.Renderer;import me.shedaniel.rei.api.client.gui.widgets.*;import me.shedaniel.rei.api.client.plugins.REIClientPlugin;import me.shedaniel.rei.api.client.registry.category.CategoryRegistry;import me.shedaniel.rei.api.client.registry.display.*;import me.shedaniel.rei.api.client.registry.entry.EntryRegistry;import me.shedaniel.rei.api.common.category.CategoryIdentifier;import me.shedaniel.rei.api.common.display.basic.BasicDisplay;import me.shedaniel.rei.api.common.entry.*;import me.shedaniel.rei.api.common.util.EntryStacks;import me.shedaniel.rei.forge.REIPluginClient;import net.minecraft.network.chat.Component;
@REIPluginClient public final class StirlingReiPlugin implements REIClientPlugin {
 private static final CategoryIdentifier<Display> TYPE=CategoryIdentifier.of("hbm","stirling");@Override public void registerCategories(CategoryRegistry event){event.add(new Category());for(var item:StirlingContent.ITEM.values())event.addWorkstations(TYPE,EntryStacks.of(item.get()));}@Override public void registerDisplays(DisplayRegistry event){for(var view:StirlingViews.views())event.add(new Display(view));}@Override public void registerEntries(EntryRegistry event){for(var stack:StirlingContent.allStacks())event.addEntry(EntryStacks.of(stack));}@Override public void registerItemComparators(me.shedaniel.rei.api.common.entry.comparison.ItemComparatorRegistry event){for(var item:StirlingContent.ITEM.values())event.register((context,stack)->stack.getOrDefault(HbmHazards.LEGACY_METADATA.get(),0),item.get());}
 private static final class Display extends BasicDisplay{final StirlingViews.View view;Display(StirlingViews.View view){super(List.of(),List.of());this.view=view;}@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}}
 private static final class Category implements DisplayCategory<Display>{@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}@Override public Component getTitle(){return Component.translatable("block.hbm.machine_stirling");}@Override public Renderer getIcon(){return EntryStacks.of(StirlingContent.ITEM.get(StirlingKind.NORMAL).get());}@Override public int getDisplayWidth(Display display){return 166;}@Override public int getDisplayHeight(){return 65;}@Override public List<Widget> setupDisplay(Display display,Rectangle bounds){return List.of(Widgets.createDrawableWidget((g,x,y,partial)->StirlingViews.draw(g,display.view,bounds.x,bounds.y)),Widgets.createSlot(new Point(bounds.x+74,bounds.y+24)).entry(EntryStacks.of(display.view.machine())).disableBackground());}}
}
